/* ---------- primitives ---------- */
const wrap = (dark, extra) => 'um' + (dark ? ' dark' : '') + (extra ? ' ' + extra : '');
const Stat = ({ net }) => (
  <div className="stat"><span>9:41</span><span>{net === 'off' ? '✕ offline · 84%' : '5G · 84%'}</span></div>
