const Ib = ({ icon, on }) => (<span className={'ibtn' + (on ? ' on' : '')}>{icon}</span>);

const Row = ({ u, cls }) => (
  <div className={'row' + (cls ? ' ' + cls : '')}>
    {cls && cls.indexOf('pressed') > -1 ? <span className="rp"></span> : null}
